package com.example.grafanapocket;

import android.appwidget.AppWidgetManager;import android.content.Context;import android.graphics.*;import org.json.*;import java.net.URLEncoder;import java.util.*;

final class NativeWidgetUpdater {
    static void update(Context context,int widgetId)throws Exception {android.content.SharedPreferences prefs=context.getSharedPreferences("widgets",Context.MODE_PRIVATE);Connection c=new SecureStore(context).get(prefs.getString("connection_"+widgetId,""));if(c==null)throw new Exception("连接不存在");String panelId=prefs.getString("panel_"+widgetId,"");if(panelId.isEmpty())throw new Exception("完整 Dashboard 暂不支持后台原生渲染");String uid=GrafanaApi.uid(c.dashboard);JSONObject dashboardResponse=new JSONObject(GrafanaApi.get(c,"/api/dashboards/uid/"+URLEncoder.encode(uid,"UTF-8")));JSONObject panel=findPanel(dashboardResponse.getJSONObject("dashboard").optJSONArray("panels"),Integer.parseInt(panelId));if(panel==null)throw new Exception("找不到 Panel #"+panelId);JSONArray targets=panel.optJSONArray("targets");if(targets==null||targets.length()==0)throw new Exception("Panel 没有查询配置");long now=System.currentTimeMillis(),from=parseFrom(prefs.getString("from_"+widgetId,"now-6h"),now);JSONObject request=new JSONObject().put("from",String.valueOf(from)).put("to",String.valueOf(now));JSONArray queries=new JSONArray();JSONObject panelDs=panel.optJSONObject("datasource");for(int i=0;i<targets.length();i++){JSONObject source=targets.optJSONObject(i);if(source==null||source.optBoolean("hide",false))continue;JSONObject q=new JSONObject(source.toString());JSONObject ds=q.optJSONObject("datasource");if(ds==null)ds=panelDs;if(ds!=null)q.put("datasource",ds);q.put("intervalMs",Math.max(1000,(now-from)/100)).put("maxDataPoints",100);if(!q.has("refId"))q.put("refId",String.valueOf((char)('A'+i)));queries.put(q);}request.put("queries",queries);JSONObject result=new JSONObject(GrafanaApi.post(c,"/api/ds/query",request));Series series=parseSeries(result);if(series.values.isEmpty())throw new Exception("查询没有返回数值");Bitmap bitmap=draw(panel,series,widgetSize(context,widgetId));WidgetCache.save(context,widgetId,bitmap);context.getSharedPreferences("widgets",Context.MODE_PRIVATE).edit().putLong("updated_"+widgetId,System.currentTimeMillis()).apply();}
    static JSONObject findPanel(JSONArray panels,int id){if(panels==null)return null;for(int i=0;i<panels.length();i++){JSONObject p=panels.optJSONObject(i);if(p==null)continue;if(p.optInt("id",-1)==id)return p;JSONObject nested=findPanel(p.optJSONArray("panels"),id);if(nested!=null)return nested;}return null;}
    static long parseFrom(String value,long now){try{if(value.startsWith("now-")&&value.length()>5){long n=Long.parseLong(value.substring(4,value.length()-1));char unit=value.charAt(value.length()-1);long factor=unit=='m'?60000L:unit=='h'?3600000L:unit=='d'?86400000L:1000L;return now-n*factor;}return Long.parseLong(value);}catch(Exception e){return now-21600000L;}}
    static Series parseSeries(JSONObject root){Series best=new Series();JSONObject results=root.optJSONObject("results");if(results==null)return best;Iterator<String> keys=results.keys();while(keys.hasNext()){JSONObject r=results.optJSONObject(keys.next());JSONArray frames=r==null?null:r.optJSONArray("frames");if(frames==null)continue;for(int f=0;f<frames.length();f++){JSONObject frame=frames.optJSONObject(f),data=frame==null?null:frame.optJSONObject("data");JSONArray values=data==null?null:data.optJSONArray("values");if(values==null)continue;for(int column=1;column<values.length();column++){JSONArray a=values.optJSONArray(column);if(a==null)continue;Series candidate=new Series();for(int i=0;i<a.length();i++){Object v=a.opt(i);if(v instanceof Number)candidate.values.add(((Number)v).doubleValue());}if(candidate.values.size()>best.values.size())best=candidate;}}}return best;}
    static Point widgetSize(Context c,int id){android.os.Bundle o=AppWidgetManager.getInstance(c).getAppWidgetOptions(id);int w=o.getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_WIDTH,180),h=o.getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_HEIGHT,100);int width=600,height=Math.max(180,Math.min(600,Math.round(width*h/(float)Math.max(1,w))));return new Point(width,height);}
    static Bitmap draw(JSONObject panel,Series series,Point size){Bitmap b=Bitmap.createBitmap(size.x,size.y,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);c.drawColor(Color.rgb(24,27,31));double last=series.values.get(series.values.size()-1);int color=thresholdColor(panel,last);Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);p.setTypeface(Typeface.create("sans",Typeface.NORMAL));p.setColor(Color.rgb(210,214,220));p.setTextAlign(Paint.Align.CENTER);p.setTextSize(Math.max(24,size.y*.10f));c.drawText(panel.optString("title","Panel"),size.x/2f,size.y*.15f,p);String text=format(panel,last);p.setTypeface(Typeface.create("sans",Typeface.BOLD));p.setColor(color);p.setTextSize(Math.min(size.x*.28f,size.y*.34f));Paint.FontMetrics fm=p.getFontMetrics();c.drawText(text,size.x/2f,size.y*.50f-(fm.ascent+fm.descent)/2,p);if(series.values.size()>1){float top=size.y*.68f,bottom=size.y*.94f;double min=Collections.min(series.values),max=Collections.max(series.values);if(max==min)max=min+1;p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(Math.max(3,size.x/180f));p.setColor(color);p.setAlpha(210);Path path=new Path();for(int i=0;i<series.values.size();i++){float x=i*size.x/(float)(series.values.size()-1),y=bottom-(float)((series.values.get(i)-min)/(max-min))*(bottom-top);if(i==0)path.moveTo(x,y);else path.lineTo(x,y);}c.drawPath(path,p);}return b;}
    static String format(JSONObject panel,double value){JSONObject fieldConfig=panel.optJSONObject("fieldConfig"),defaults=fieldConfig==null?null:fieldConfig.optJSONObject("defaults");int decimals=defaults==null?-1:defaults.optInt("decimals",-1);String unit=defaults==null?"":defaults.optString("unit","");String number;if(decimals>=0)number=String.format(Locale.getDefault(),"%."+decimals+"f",value);else if(Math.abs(value-Math.rint(value))<0.0001)number=String.valueOf((long)Math.rint(value));else number=String.format(Locale.getDefault(),"%.1f",value);if(unit.contains("percent"))number+="%";return number;}
    static int thresholdColor(JSONObject panel,double value){int color=Color.rgb(115,191,105);JSONObject fc=panel.optJSONObject("fieldConfig"),defaults=fc==null?null:fc.optJSONObject("defaults"),thresholds=defaults==null?null:defaults.optJSONObject("thresholds");JSONArray steps=thresholds==null?null:thresholds.optJSONArray("steps");if(steps!=null)for(int i=0;i<steps.length();i++){JSONObject s=steps.optJSONObject(i);if(s==null)continue;Object raw=s.opt("value");if(raw==JSONObject.NULL||!(raw instanceof Number)||value>=((Number)raw).doubleValue())color=parseColor(s.optString("color","green"),color);}return color;}
    static int parseColor(String s,int fallback){Map<String,Integer> m=new HashMap<>();m.put("green",Color.rgb(115,191,105));m.put("red",Color.rgb(242,73,92));m.put("yellow",Color.rgb(250,222,42));m.put("orange",Color.rgb(255,152,48));if(m.containsKey(s))return m.get(s);try{return Color.parseColor(s);}catch(Exception e){return fallback;}}
    static final class Series{final List<Double> values=new ArrayList<>();}
}
